def transform(grid):
    bg = 3
    h, w = len(grid), len(grid[0])

    # Find all non-background rows
    fg_rows = [r for r in range(h) if any(grid[r][c] != bg for c in range(w))]

    # Group rows into objects (separated by >5 consecutive background rows)
    objects = []
    if len(fg_rows) > 0:
        obj = [fg_rows[0]]
        for i in range(1, len(fg_rows)):
            if fg_rows[i] - fg_rows[i-1] > 5:
                objects.append(obj)
                obj = [fg_rows[i]]
            else:
                obj.append(fg_rows[i])
        objects.append(obj)

    # Apply transformation: 2nd object modified based on 1st
    if len(objects) >= 2:
        top = objects[0]
        bot = objects[1]
        for i in range(min(len(top), len(bot))):
            rt, rb = top[i], bot[i]
            if grid[rt][-1] != bg and grid[rb][-1] == bg:
                grid[rb][-1] = 1
    return grid
